static BlackGuestFunction black_resolve_guest_function(uint32_t guest_va)
{
    size_t low = 0, high = sizeof(black_guest_functions) / sizeof(black_guest_functions[0]);
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (black_guest_functions[middle].guest_va < guest_va) low = middle + 1;
        else high = middle;
    }
    return low < sizeof(black_guest_functions) / sizeof(black_guest_functions[0]) && black_guest_functions[low].guest_va == guest_va ? black_guest_functions[low].host_function : 0;
}

static uint32_t black_guest_function_count(void)
{
    return (uint32_t)(sizeof(black_guest_functions) / sizeof(black_guest_functions[0]));
}

